-- YG-755: toplu dışa aktarma; yetki, gerekçe, amaç, kayıt sınırı, ek onay ve indirilen dosya kimliği kaydı.
CREATE TABLE disa_aktarim (kimlik uuid PRIMARY KEY DEFAULT gen_random_uuid(), veri_seti text NOT NULL, alanlar text[] NOT NULL CHECK (cardinality(alanlar) > 0), bicim text NOT NULL DEFAULT 'CSV' CHECK (bicim IN ('CSV')), amac text NOT NULL, gerekce text NOT NULL, kayit_sayisi integer NOT NULL, hassas boolean NOT NULL, durum text NOT NULL CHECK (durum IN ('Hazır', 'Onayda', 'Reddedildi', 'İndirildi', 'Süresi Doldu')), talep_eden_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), son_gecerlilik timestamptz, olusturma_zamani timestamptz NOT NULL DEFAULT now());
CREATE TABLE disa_aktarim_indirme (dosya_kimligi uuid PRIMARY KEY DEFAULT gen_random_uuid(), aktarim_ref uuid NOT NULL REFERENCES disa_aktarim (kimlik), kayit_sayisi integer NOT NULL, ozet_sha256 text NOT NULL, indiren_ref text NOT NULL REFERENCES kullanici_hesabi (kimlik), adres text, zaman timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON disa_aktarim TO yatonet_uygulama; GRANT SELECT, INSERT ON disa_aktarim_indirme TO yatonet_uygulama;
